import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import type { PrimitiveProps } from "../primitives";

// Repeating dot grid over a warm orange field. Everything loops by construction:
// the drift is a modulo of the tile size (so the pattern lands exactly where it
// started every cycle and the number never grows), and the breathing is a sine.
// Nothing settles, nothing freezes - safe for a 5s clip or a 5min one.
const TILE = 84; // px between dots
const DRIFT_SECONDS = 16; // one full tile of travel per cycle
const BREATH_SECONDS = 11;

const dotLayer = (alpha: number, radius: number) =>
  `radial-gradient(circle at 50% 50%, rgba(255,255,255,${alpha}) 0px, rgba(255,255,255,${alpha}) ${radius}px, rgba(255,255,255,0) ${radius + 1.2}px)`;

const OrangeDotGrid: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();

  const drift = (frame / (DRIFT_SECONDS * fps)) % 1; // 0 -> 1, forever
  const breath = Math.sin((frame / (BREATH_SECONDS * fps)) * Math.PI * 2);

  return (
    <AbsoluteFill style={{ backgroundColor: "#E8701A" }}>
      {/* warm-to-deep vertical wash so the flat orange has some body */}
      <AbsoluteFill
        style={{
          backgroundImage:
            "linear-gradient(180deg, #F28A2E 0%, #E8701A 46%, #C9540F 100%)",
        }}
      />

      {/* main dot grid, drifting diagonally by exactly one tile per cycle */}
      <AbsoluteFill
        style={{
          backgroundImage: dotLayer(0.16, 4),
          backgroundSize: `${TILE}px ${TILE}px`,
          backgroundPosition: `${drift * TILE}px ${drift * TILE}px`,
          opacity: interpolate(breath, [-1, 1], [0.82, 1]),
        }}
      />

      {/* second, larger grid drifting the other way - depth without busyness */}
      <AbsoluteFill
        style={{
          backgroundImage: dotLayer(0.09, 6),
          backgroundSize: `${TILE * 2.5}px ${TILE * 2.5}px`,
          backgroundPosition: `${-drift * TILE * 2.5}px ${drift * TILE * 2.5}px`,
        }}
      />

      {/* slow highlight that swells and fades - keeps the frame from feeling static */}
      <AbsoluteFill
        style={{
          backgroundImage:
            "radial-gradient(120% 70% at 50% 18%, rgba(255,196,120,0.42) 0%, rgba(255,196,120,0) 62%)",
          opacity: interpolate(breath, [-1, 1], [0.35, 0.85], {
            easing: Easing.inOut(Easing.ease),
          }),
        }}
      />

      {/* vignette so foreground text keeps contrast at the edges */}
      <AbsoluteFill
        style={{
          backgroundImage:
            "radial-gradient(80% 58% at 50% 50%, rgba(0,0,0,0) 40%, rgba(90,32,0,0.34) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default OrangeDotGrid;
